package dev.zomboid.mts;
import java.util.*;
public final class Workshop {
 static String p="minecrafttransportsimulator.";static Map<Object,List<Object>> labels=new WeakHashMap<>(),icons=new WeakHashMap<>();
 public record Entry(String label,Double condition){}
 public static int band(Double condition){return condition==null?3:condition>66?0:condition>33?1:2;}
 static double zone(Object v,String id){Object var=R.call(v,"getOrCreateVariable","pz_condition_"+id);return Maintenance.condition(R.num(R.get(var,"currentValue")));}
 public static List<Entry> body(Object v){List<Entry> rows=new ArrayList<>();rows.add(new Entry("Chasis",Mechanics.health(v)*100));rows.add(new Entry("Defensa delantera",zone(v,"front")));rows.add(new Entry("Defensa trasera",zone(v,"rear")));if(!"quad".equals(R.get(R.get(v,"definition"),"systemName"))){rows.add(new Entry("Capo",zone(v,"hood")));rows.add(new Entry("Puerta izquierda",zone(v,"door_left")));rows.add(new Entry("Puerta derecha",zone(v,"door_right")));rows.add(new Entry("Parabrisas",zone(v,"windshield")));rows.add(new Entry("Ventanas izquierdas",zone(v,"window_left")));rows.add(new Entry("Ventanas derechas",zone(v,"window_right")));rows.add(new Entry("Cristal trasero",zone(v,"rear_window")));}return rows;}
 public static List<Entry> equipment(Object v){List<Entry> rows=new ArrayList<>();List<?> slots=(List<?>)R.get(R.get(v,"definition"),"parts"),installed=(List<?>)R.get(v,"partsInSlots");int wheel=0,seat=0,motor=0;double split=slots.stream().filter(s->((List<?>)R.get(s,"types")).stream().anyMatch(t->t.toString().startsWith("ground_wheel"))).mapToDouble(s->R.num(R.get(R.get(s,"pos"),"z"))).average().orElse(0);for(int i=0;i<slots.size();i++){Object slot=slots.get(i),part=i<installed.size()?installed.get(i):null;List<?> types=(List<?>)R.get(slot,"types");String label=null;if(types.stream().anyMatch(t->t.toString().startsWith("ground_wheel"))&&wheel++<6){Object pos=R.get(slot,"pos");label="Rueda "+(R.num(R.get(pos,"z"))>=split?"del. ":"tras. ")+(R.num(R.get(pos,"x"))>0?"izq.":"der.");}else if(types.stream().anyMatch(t->t.toString().startsWith("seat"))&&seat++<6)label=R.yes(R.get(slot,"isController"))?"Asiento conductor":"Asiento "+seat;else if(types.stream().anyMatch(t->t.toString().startsWith("engine"))&&motor++<2)label="Motor "+motor;if(label!=null)rows.add(new Entry(label,part==null?null:Mechanics.health(part)*100));}rows.add(new Entry("Bateria (carga)",R.num(R.call(Mechanics.class,"battery",v))*100));rows.add(new Entry("Combustible",R.num(R.call(Mechanics.class,"fuel",v))*100));return rows;}
 static Object label(Object gui,int x,int y,String text,float size){return R.call(Mechanics.class,"label",gui,x,y,text,size,R.get(R.type(p+"baseclasses.ColorRGB"),"WHITE"));}
 public static void setup(Object gui){if(FamilyWorkshop.special(R.get(gui,"vehicle"))){FamilyWorkshop.setup(gui);return;}int x=((Number)R.get(gui,"guiLeft")).intValue(),y=((Number)R.get(gui,"guiTop")).intValue();label(gui,x+18,y+16,"MECANICA DEL VEHICULO",1.1f);Object v=R.get(gui,"vehicle"),def=R.get(v,"subDefinition");String name=Objects.toString(R.get(def,"name"),R.get(R.get(v,"definition"),"systemName").toString());label(gui,x+210,y+16,name,1.1f);label(gui,x+210,y+54,"CARROCERIA",1f);label(gui,x+430,y+54,"PIEZAS / SUMINISTROS",1f);List<Object> fields=new ArrayList<>();fields.add(label(gui,x+210,y+35,"",1f));for(int col=0;col<2;col++)for(int i=0;i<16;i++)fields.add(label(gui,x+210+col*220,y+76+i*15,"",.9f));labels.put(gui,fields);List<Object> regions=new ArrayList<>();int[][] positions={{52,77,70,54},{47,132,78,35},{55,171,64,83},{29,169,22,90},{123,169,22,90},{48,260,76,24},{53,285,66,19},{23,135,20,32},{133,135,20,32},{23,259,20,32},{133,259,20,32},{164,78,28,34}};for(int i=0;i<positions.length;i++){int[] rect=positions[i];Object icon=R.make(p+"guis.components.GUIComponentCutout",gui,x+rect[0],y+rect[1],rect[2],rect[3],640+i%6*64,i/6*256,64,64);R.set(icon,"ignoreGUILightingState",true);R.call(gui,"addComponent",icon);regions.add(icon);}icons.put(gui,regions);R.call(gui,"addComponent",R.make("dev.zomboid.mts.ModeButton",gui,x+210,y+336));R.call(gui,"addComponent",R.make("dev.zomboid.mts.VehicleButton",gui,x+475,y+335,125,"hood","Abrir / cerrar capo"));}
 public static void close(Object gui){labels.remove(gui);icons.remove(gui);FamilyWorkshop.close(gui);}
 static void put(Object label,Entry row){String text=row==null?"":row.label()+": "+(row.condition()==null?"No instalado":Math.round(row.condition())+"%");R.set(label,"text",(row==null?"":switch(band(row.condition())){case 0->"§a";case 1->"§e";case 2->"§c";default->"§7";})+text);}
 public static void state(Object gui){if(FamilyWorkshop.special(R.get(gui,"vehicle"))){FamilyWorkshop.state(gui);return;}Object v=R.get(gui,"vehicle");List<Object> fields=labels.get(gui);if(fields==null)return;R.set(fields.get(0),"text",String.format("Estado general: %.0f%%",Mechanics.health(v)*100));List<Entry> body=body(v),equipment=equipment(v);for(int col=0;col<2;col++){List<Entry> list=col==0?body:equipment;for(int i=0;i<16;i++)put(fields.get(1+col*16+i),i<list.size()?list.get(i):null);}java.util.OptionalDouble engineHealth=((Collection<?>)R.get(v,"engines")).stream().mapToDouble(e->Mechanics.health(e)*100).min();Double engine=engineHealth.isPresent()?engineHealth.getAsDouble():null;List<Double> wheelStates=new ArrayList<>();for(String target:List.of("Rueda del. izq.","Rueda del. der.","Rueda tras. izq.","Rueda tras. der."))wheelStates.add(equipment.stream().filter(e->e.label().equals(target)).findFirst().map(Entry::condition).orElse(null));Double[] states={zone(v,"hood"),zone(v,"windshield"),Mechanics.health(v)*100,zone(v,"door_left"),zone(v,"door_right"),zone(v,"rear_window"),zone(v,"rear"),wheelStates.size()>0?wheelStates.get(0):null,wheelStates.size()>1?wheelStates.get(1):null,wheelStates.size()>2?wheelStates.get(2):null,wheelStates.size()>3?wheelStates.get(3):null,engine};List<Object> regions=icons.get(gui);for(int i=0;i<regions.size();i++)R.set(regions.get(i),"textureYOffset",i/6*256+band(states[i])*64);}
}
